 public static function text(string$s,array$messages,array$values=[]):string{if(!isset($messages[self::key($s)]))return InventoryHistoryMessages::text($s,$messages,$values);$replace=[];foreach($values as$k=>$v)$replace['{'.$k.'}']=(string)$v;return strtr($messages[self::key($s)],$replace);}
